<script>(()=>{if(window.lucide)lucide.createIcons({attrs:{'stroke-width':1.75}});const theme=document.getElementById('theme-toggle');const sync=()=>{const dark=document.documentElement.classList.contains('dark');if(theme){theme.innerHTML=`<i data-lucide="${dark?'sun':'moon'}" stroke-width="1.75" class="h-4 w-4"></i>`;if(window.lucide)lucide.createIcons({attrs:{'stroke-width':1.75}})}};theme?.addEventListener('click',()=>{const dark=!document.documentElement.classList.contains('dark');document.documentElement.classList.toggle('dark',dark);document.documentElement.classList.toggle('light',!dark);try{localStorage.setItem('bumcash_theme',dark?'dark':'light')}catch(_){}sync()});sync();const toggle=document.getElementById('password-toggle');toggle?.addEventListener('click',()=>{const input=document.getElementById('password');const show=input.type==='password';input.type=show?'text':'password';toggle.innerHTML=`<i data-lucide="${show?'eye-off':'eye'}" stroke-width="1.75" class="h-4 w-4"></i>`;toggle.setAttribute('aria-label',show?'Sembunyikan password':'Tampilkan password');if(window.lucide)lucide.createIcons({attrs:{'stroke-width':1.75}})})})();</script>
